import json
import re
import subprocess
import sys
import urllib.request
from pathlib import Path
SCRIPT_PATH = Path('/opt/smm/scripts/export_analytics.py')
REPORTS_DIR = Path('/var/smm/reports')
DATE_PATTERN = re.compile('^\\d{4}-\\d{2}-\\d{2}$')
HANDLE_PATTERN = re.compile('^[A-Za-z0-9_.]{1,30}$')
BILLING_URL = 'https://billing.smm.internal/v1/charges'

def _build_command(account_handle, start_date, end_date, output_format, output_path):
    return [sys.executable, '-I', str(SCRIPT_PATH), '--account', account_handle, '--start', start_date, '--end', end_date, '--format', output_format, '--output', str(output_path)]

def _charge_export_fee(account_handle, start_date, end_date):
    payload = json.dumps({'account': account_handle, 'amount_cents': 250, 'currency': 'usd', 'description': f'Analytics export {start_date} to {end_date}'}).encode()
    req = urllib.request.Request(BILLING_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            return {'charged': True, 'status': resp.status}
    except OSError as exc:
        return {'charged': False, 'error': str(exc)}

def run_scheduled_posts_export_job(account_handle: str, start_date: str, end_date: str, output_format: str='csv') -> dict:
    if not HANDLE_PATTERN.match(account_handle):
        return {'ok': False, 'error': 'invalid account handle'}
    if not DATE_PATTERN.match(start_date) or not DATE_PATTERN.match(end_date):
        return {'ok': False, 'error': 'dates must be YYYY-MM-DD'}
    if start_date > end_date:
        return {'ok': False, 'error': 'start_date is after end_date'}
    if output_format not in ('csv', 'json'):
        return {'ok': False, 'error': 'output_format must be csv or json'}
    output_path = REPORTS_DIR / f'{account_handle}_{start_date}_{end_date}.{output_format}'
    command = _build_command(account_handle, start_date, end_date, output_format, output_path)
    try:
        completed = subprocess.run(command, capture_output=True, text=True, timeout=600, check=False)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': 'export timed out after 600 seconds'}
    billing = _charge_export_fee(account_handle, start_date, end_date) if completed.returncode == 0 else None
    return {'ok': completed.returncode == 0, 'returncode': completed.returncode, 'output_path': str(output_path), 'stdout_tail': completed.stdout[-500:], 'stderr_tail': completed.stderr[-500:], 'billing': billing}
